dence, so 'the new dispatcher is ready' cannot be defined or observed."},{"id":"EG3","locator_hint":{"path":"dispatch/dispatch.go","symbol":"aggrGroupsPerRoute"},"summary":"aggrGroupsPerRoute is keyed by *Route; no supplied source shows whether aggregation groups remain valid or transferable when the routing tree is rebuilt on reload, so in-place dispatcher reuse cannot be justified as safe."}],"instruction":"Prior claims are not trusted facts or edit permission. Cite only exact current evidence_catalog records; unavailable IDs cannot support claims. Reassess the listed gaps and prior static inference. Missing final/live observation limits verification, not source-supported fault inference. Revise or withdraw claims when current evidence warrants it; explain in causal_explanation/evidence_gaps.summary. Missing repair helpers may be introduced only with evidenced caller/interface prerequisites and edit permission. Unobserved outcomes remain UNKNOWN. Do not automatically retain old verdicts.","omitted_claim_count":0,"prior_diagnosis_digest":"806a88924d1d4deea1d23fba8d21dbf156dd8325c5ba95a83ffc80766cfe9c0a","snapshot_id":"007325c7f55977c4afd2dfae9e3213373126ad9d11f0854be1d3f54f8fe89308"},"evidence_catalog":[{"content_digest":"c76cc3560e30e77d5a52da462fbb9cef2b2e29a0397ebd9e6ae55bca62324799","excerpt":"// Run starts dispatching alerts incoming via the updates channel.
func (d *Dispatcher) Run(dispatchStartTime time.Time) {
	d.done = make(chan struct{})

	d.mtx.Lock()
	d.logger.Debug("preparing to start", "startTime", dispatchStartTime)
	d.startTimer = time.NewTimer(time.Until(dispatchStartTime))
	d.state = DispatcherStateWaitingToStart
	d.logger.Debug("setting state", "state", "waiting_to_start")
	d.aggrGroupsPerRoute = map[*Route]map[model.Fingerprint]*aggrGroup{}
	d.aggrGroupsNum = 0
	d.metrics.aggrGroups.Set(0)
	d.ctx, d.cancel = context.WithCancel(context.Background())
	d.mtx.Unlock()

	d.run(d.alerts.Subscribe("dispatcher"))
	close(d.done)
}
