func (d *Dispatcher) Stop() {
	if d == nil {
		return
	}
	d.mtx.Lock()
	if d.cancel == nil {
		d.mtx.Unlock()
		return
	}
	d.cancel()
	d.cancel = nil
	d.mtx.Unlock()

	<-d.done
}
","id":"SRC-CU-HELPER-528d2e002820be1b","kind":"SOURCE_SPAN","locator":{"end_line":331,"path":"dispatch/dispatch.go","start_line":316},"origin":"selected candidate CU-HELPER-528d2e002820be1b","snapshot_id":"007325c7f55977c4afd2dfae9e3213373126ad9d11f0854be1d3f54f8fe89308"},{"content_digest":"ebcfd89c062988b8eafd089a88419560c6d7beea7cda21e4fcedf8bdd5dbf3d3","excerpt":"func (d *Dispatcher) runAG(ag *aggrGroup) {
	if ag.running.Load() {
		return
	}
	go ag.run(func(ctx context.Context, alerts ...*types.Alert) bool {
		_, _, err := d.stage.Exec(ctx, d.logger, alerts...)
		if err != nil {
			logger := d.logger.With("aggrGroup", ag.GroupKey(), "num_alerts", len(alerts), "err", err)
			if errors.Is(ctx.Err(), context.Canceled) {
				// It is expected for the context to be canceled on
				// configuration reload or shutdown. In this case, the
				// message should only be logged at the debug level.
				logger.Debug("Notify for alerts failed")
			} else {
				logger.Error("Notify for alerts failed")
			}
		}
		return err == nil
	})
}
